VALUES ('club_louisville-mahjong-studio-one', 'Mahjong Studio One', 'louisville-mahjong-studio-one', 'Louisville mahjong studio with open play and classes. Its official site refers to the national Mahjong card, but does not explicitly name American Mahjong or the National Mah Jongg League; retained as NEEDS_REVIEW pending variant confirmation.', (SELECT id FROM City WHERE name = 'Louisville' AND state = 'KY'), '8109 La Grange Road, Louisville, KY 40222', 'https://www.mahjongstudio1.com/', '(502) 885-9956', 'manager@mahjongstudio1.com', NULL, NULL, 1, 1, 1, 1, 0, 0, NULL, 'Open play and classes; current site lists MAHJ GHUOL''S NIGHT OUT 2.0 on October 27, 6:00-9:00 PM', 'https://www.mahjongstudio1.com/', '2026-09-30', 'NEEDS_REVIEW')
